# Generated by build.py from recipe.yml for recipe http-stop-a-client-hammering-a-refused-login. Do not edit.
Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', '--directory', 'site', '--user', 'app:s3cret', '--user', 'other:o-secret', '--fault', '"refuse-login;account=app"', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -sS -f --retry 3 --retry-delay 1 --digest -u app:s3cret -o NUL -w "%{http_code} %{num_retries}\n" http://127.0.0.1:8080/hello.txt } finally { Stop-Process $server0 }
